//! LW008: the package name looks like a typo of a popular package.
//!
//! Attackers publish `expres` or `cross_env` hoping someone mistypes
//! `express` or `cross-env`. We compare the name with a list of popular
//! packages (`data/popular.txt`, generated by `scripts/build_popular.ts`):
//! - Damerau-Levenshtein distance (insertions, deletions, substitutions and
//!   swaps of two neighbours) of 1 for names of 5 to 9 characters, 2 for 10
//!   or more; names under 5 characters are skipped (too many short names
//!   are one edit apart by chance),
//! - or the same name once `-`, `_`, `.`, `@` and `/` are removed
//!   (separator and scope confusion: `cross_env`, `@types-node`).
//!
//! A name that is itself on the popular list is never flagged.

use std::sync::OnceLock;

use super::{Finding, Rule, Severity};
use crate::context::PackageContext;

pub struct PossibleTyposquat;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PopularPackage {
    pub name: String,
    pub weekly_downloads: u64,
}

/// The list compiled into the binary. `include_str!` reads the file at
/// compile time, so the binary does not need the data file at runtime.
const POPULAR_TXT: &str = include_str!("../../data/popular.txt");

/// Parse `name<TAB>weekly_downloads` lines; `#` starts a comment.
pub fn parse_popular(text: &str) -> Vec<PopularPackage> {
    text.lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .filter_map(|line| {
            let mut parts = line.split('\t');
            let name = parts.next()?.trim().to_string();
            let weekly_downloads = parts
                .next()
                .and_then(|d| d.trim().parse().ok())
                .unwrap_or(0);
            Some(PopularPackage {
                name,
                weekly_downloads,
            })
        })
        .collect()
}

/// The embedded list, parsed once on first use.
pub fn popular_packages() -> &'static [PopularPackage] {
    static LIST: OnceLock<Vec<PopularPackage>> = OnceLock::new();
    LIST.get_or_init(|| parse_popular(POPULAR_TXT))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Similarity {
    EditDistance(usize),
    SeparatorConfusion,
}

/// Lowercase and drop separators: `@Types/node_js` -> `typesnodejs`.
fn squash(name: &str) -> String {
    name.chars()
        .filter(|c| !matches!(c, '-' | '_' | '.' | '@' | '/'))
        .flat_map(char::to_lowercase)
        .collect()
}

/// Allowed edit distance for a name of `len` characters.
fn max_distance(len: usize) -> usize {
    match len {
        0..=4 => 0,
        5..=9 => 1,
        _ => 2,
    }
}

/// The popular package `name` most likely imitates, if any.
pub fn closest_popular<'a>(
    name: &str,
    popular: &'a [PopularPackage],
) -> Option<(&'a PopularPackage, Similarity)> {
    if popular.iter().any(|p| p.name == name) {
        return None;
    }
    let squashed = squash(name);
    if let Some(p) = popular.iter().find(|p| squash(&p.name) == squashed) {
        return Some((p, Similarity::SeparatorConfusion));
    }
    let len = name.chars().count();
    let limit = max_distance(len);
    if limit == 0 {
        return None;
    }
    popular
        .iter()
        // Cheap length filter before the O(n*m) distance computation.
        .filter(|p| p.name.chars().count().abs_diff(len) <= limit)
        .filter_map(|p| {
            let d = strsim::damerau_levenshtein(name, &p.name);
            (d > 0 && d <= limit).then_some((p, d))
        })
        // Closest first; among equals, the most downloaded.
        .min_by(|(a, da), (b, db)| da.cmp(db).then(b.weekly_downloads.cmp(&a.weekly_downloads)))
        .map(|(p, d)| (p, Similarity::EditDistance(d)))
}

impl Rule for PossibleTyposquat {
    fn id(&self) -> &'static str {
        "LW008"
    }
    fn name(&self) -> &'static str {
        "Possible typosquat"
    }
    fn severity(&self) -> Severity {
        Severity::Medium
    }
    fn description(&self) -> &'static str {
        "name within Damerau-Levenshtein distance 1-2 (by length) of a popular package, or the \
         same name with different separators or scope, and not itself popular"
    }

    fn check(&self, ctx: &PackageContext) -> Vec<Finding> {
        let Some((target, similarity)) = closest_popular(&ctx.name, popular_packages()) else {
            return Vec::new();
        };
        let how = match similarity {
            Similarity::EditDistance(1) => "is 1 edit away from".to_string(),
            Similarity::EditDistance(d) => format!("is {d} edits away from"),
            Similarity::SeparatorConfusion => {
                "differs only in separators or scope from".to_string()
            }
        };
        let evidence = format!(
            "\"{}\" {how} \"{}\" ({} weekly downloads)",
            ctx.name, target.name, target.weekly_downloads
        );
        vec![self.finding(
            ctx,
            None,
            None,
            &evidence,
            format!(
                "The name looks like a misspelling of the popular package {}.",
                target.name
            ),
        )]
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::rules::test_helpers::ctx;

    fn list() -> Vec<PopularPackage> {
        parse_popular(
            "# comment\nexpress\t100\ncross-env\t50\nlodash\t200\nreact\t300\n@types/node\t10\n",
        )
    }

    #[test]
    fn edit_distance_typos() {
        let l = list();
        assert_eq!(
            closest_popular("expres", &l).map(|(p, s)| (p.name.as_str(), s)),
            Some(("express", Similarity::EditDistance(1)))
        );
        // A swap of two neighbours is one Damerau-Levenshtein edit.
        assert_eq!(
            closest_popular("lodahs", &l).map(|(p, s)| (p.name.as_str(), s)),
            Some(("lodash", Similarity::EditDistance(1)))
        );
    }

    #[test]
    fn separator_and_scope_confusion() {
        let l = list();
        assert_eq!(
            closest_popular("cross_env", &l).map(|(p, s)| (p.name.as_str(), s)),
            Some(("cross-env", Similarity::SeparatorConfusion))
        );
        assert_eq!(
            closest_popular("types-node", &l).map(|(_, s)| s),
            Some(Similarity::SeparatorConfusion)
        );
    }

    #[test]
    fn popular_names_and_short_or_distant_names_are_fine() {
        let l = list();
        assert_eq!(closest_popular("express", &l), None);
        assert_eq!(closest_popular("reac", &l), None); // under 5 characters
        assert_eq!(closest_popular("expensive", &l), None);
    }

    #[test]
    fn embedded_list_is_loaded_and_rule_reports() {
        assert!(popular_packages().len() > 100);
        assert!(popular_packages().iter().any(|p| p.name == "express"));
        let c = ctx("expresss", &[("package.json", "{}")]);
        let f = PossibleTyposquat.check(&c);
        assert_eq!(f.len(), 1);
        assert!(f[0].evidence.contains("\"express\""));
        assert!(PossibleTyposquat.check(&ctx("express", &[])).is_empty());
    }
}
